 * Minimal, correct memoized-selector library (reselect-style).
 *
 * - defaultMemoize(fn, equalityCheck): memoizes a single function on its
 *   last arguments, cache size 1, keyed with a pluggable equality check.
 * - createSelector(inputSelectors, combiner): builds a selector that
 *   recomputes only when input results are not reference-equal to the
 *   previous run. Exposes recomputations() for testing.
 * - createStructuredSelector({key: selector}): maps state to an object of
 *   selector outputs; identity-stable when all sub-selectors are unchanged.
 */

export function defaultEqualityCheck(a, b) {
  return a === b;
}

/**
 * Memoize `func` with a cache size of 1: the last arguments and last result
 * are remembered. On each call, arguments are compared pairwise against the
 * previous call's arguments using `equalityCheck`; if all match, the cached
 * result is returned and `func` is not invoked.
 */
export function defaultMemoize(func, equalityCheck = defaultEqualityCheck) {
  if (typeof equalityCheck !== 'function') {
    throw new TypeError('equalityCheck must be a function');
  }
  let lastArgs = null;
  let lastResult;
  let hasComputed = false;

  const memoized = function (...args) {
    if (
      hasComputed &&
      lastArgs !== null &&
      lastArgs.length === args.length &&
      args.every((arg, i) => equalityCheck(arg, lastArgs[i]))
    ) {
      return lastResult;
    }
    lastArgs = args;
    lastResult = func.apply(null, args);
    hasComputed = true;
    return lastResult;
  };

  memoized.clearCache = () => {
    lastArgs = null;
    hasComputed = false;
    lastResult = undefined;
  };

  return memoized;
}

function getDependencies(func) {
  return Array.isArray(func) ? func : func.dependencies;
}

/**
 * createSelector(inputSelectors, combiner) -> selector
 *
 * inputSelectors: array of functions taking (state, ...rest)
 * combiner: (...inputResults) => output
 *
 * The combiner runs only when at least one input result differs from the
 * previous run under reference equality (`===`). The resulting selector
 * carries:
 *   - resultFunc: the combiner
 *   - dependencies: the input selectors
 *   - recomputations(): number of times the combiner has actually executed
 */
export function createSelector(inputSelectors, combiner) {
  if (!Array.isArray(inputSelectors)) {
    throw new TypeError('createSelector expects an array of input selectors');
  }
  for (const sel of inputSelectors) {
    if (typeof sel !== 'function') {
      throw new TypeError('every input selector must be a function');
    }
  }
  if (typeof combiner !== 'function') {
    throw new TypeError('combiner must be a function');
  }

  let lastInputResults = null;
  let lastComposedResult;
  let hasComputed = false;
  let recomputeCount = 0;

  const selector = function (state, ...rest) {
    const inputResults = new Array(inputSelectors.length);
    for (let i = 0; i < inputSelectors.length; i++) {
      inputResults[i] = inputSelectors[i](state, ...rest);
    }

    if (
      hasComputed &&
      lastInputResults !== null &&
      lastInputResults.length === inputResults.length &&
      inputResults.every((r, i) => r === lastInputResults[i])
    ) {
      return lastComposedResult;
    }

    // Only now allocate/store the new inputs.
    lastInputResults = inputResults;
    lastComposedResult = combiner(...inputResults);
    hasComputed = true;
    recomputeCount++;
    return lastComposedResult;
  };

  selector.resultFunc = combiner;
  selector.dependencies = inputSelectors;
  selector.recomputations = () => recomputeCount;
  selector.resetRecomputations = () => {
    recomputeCount = 0;
    return recomputeCount;
  };
  selector.clearCache = () => {
    lastInputResults = null;
    hasComputed = false;
    lastComposedResult = undefined;
    recomputeCount = 0;
  };

  return selector;
}

/**
 * createStructuredSelector({ key: selector, ... }) -> selector
 *
 * Returns a selector producing { key: selector(state), ... }. Each entry is
 * computed once per call, but the returned object is a brand-new object only
 * when at least one value changed by reference equality; otherwise the
 * previous object instance is returned, so downstream identity checks hold.
 */
export function createStructuredSelector(selectors, selectorCreator = createSelector) {
  if (
    typeof selectors !== 'object' ||
    selectors === null ||
    Array.isArray(selectors)
  ) {
    throw new TypeError(
      'createStructuredSelector expects a plain object of selectors'
    );
  }
  const keys = Object.keys(selectors);
  for (const key of keys) {
    if (typeof selectors[key] !== 'function') {
      throw new TypeError(`selector for key "${key}" must be a function`);
    }
  }

  return function (state, ...rest) {
    let changed = false;
    const result = {};
    for (const key of keys) {
      const value = selectors[key](state, ...rest);
      result[key] = value;
      changed = changed || value !== selectors.lastValues?.[key];
    }
    if (!changed && selectors.lastResult !== undefined) {
      return selectors.lastResult;
    }
    selectors.lastValues = result;
    selectors.lastResult = result;
    return result;
  };
}
