result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/selectors/test/index.test.mjs", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import {
  createSelector,
  createStructuredSelector,
  defaultMemoize,
  defaultEqualityCheck,
} from '../src/index.mjs';

// ---------------------------------------------------------------------------
// defaultMemoize
// ---------------------------------------------------------------------------

test('defaultMemoize: cache size 1, keyed on reference-equal args', () => {
  let calls = 0;
  const fn = (a, b) => {
    calls++;
    return a + b;
  };
  const memoized = defaultMemoize(fn);

  assert.equal(memoized(1, 2), 3);
  assert.equal(memoized(1, 2), 3);
  assert.equal(calls, 1); // second call hit the cache

  assert.equal(memoized(1, 3), 4);
  assert.equal(calls, 2); // different arg -> recompute

  // Cache size 1: going back to previous args recomputes.
  assert.equal(memoized(1, 2), 3);
  assert.equal(calls, 3);
});

test('defaultEqualityCheck is strict reference equality', () => {
  const a = { x: 1 };
  assert.ok(defaultEqualityCheck(a, a));
  assert.ok(!defaultEqualityCheck({ x: 1 }, { x: 1 }));
  assert.ok(defaultEqualityCheck(NaN, NaN) === false); // === semantics
});

// ---------------------------------------------------------------------------
// createSelector: recomputation counting across relevant/irrelevant updates
// ---------------------------------------------------------------------------

function makeState() {
  return {
    todos: [
      { id: 1, text: 'write lib', done: true },
      { id: 2, text: 'write tests', done: false },
    ],
    ui: { theme: 'dark', drawerOpen: false },
  };
}

const selectTodos = (state) => state.todos;
const selectVisibleCount = createSelector(
  [selectTodos],
  (todos) => todos.filter((t) => t.done).length
);

test('combiner skipped when top-level state changed but relevant branch did not', () => {
  const s1 = makeState();
  const first = selectVisibleCount(s1);
  assert.equal(first, 1);
  assert.equal(selectVisibleCount.recomputations(), 1);

  // New top-level object; ui branch changed; todos array is the SAME reference.
  const s2 = { ...s1, ui: { ...s1.ui, theme: 'light' } };
  assert.notEqual(s1, s2); // state itself changed identity
  assert.equal(selectVisibleCount(s2), 1);
  assert.equal(selectVisibleCount.recomputations(), 1); // no recompute

  // Relevant branch changes -> recompute.
  const s3 = { ...s2, todos: [...s2.todos, { id: 3, text: 'ship', done: true }] };
  assert.equal(selectVisibleCount(s3), 2);
  assert.equal(selectVisibleCount.recomputations(), 2);

  // Same reference again -> no recompute.
  assert.equal(selectVisibleCount(s3), 2);
  assert.equal(selectVisibleCount.recomputations(), 2);
});

test('recomputations tracks only actual combiner executions over a sequence', () => {
  const selector = createSelector([(s) => s.items], (items) => items.length);
  const items = [1, 2, 3];
  let n = 0;
  for (const _ of [0, 1]) {
    const state = { items, irrelevant: n++ };
    selector(state);
    selector(state);
  }
  assert.equal(selector.recomputations(), 1);
  selector({ items: [1, 2, 3, 4], irrelevant: 99 });
  assert.equal(selector.recomputations(), 2);
  selector.resetRecomputations();
  assert.equal(selector.recomputations(), 0);
  selector({ items, irrelevant: -1 });
  assert.equal(selector.recomputations(), 1);
});

// ---------------------------------------------------------------------------
// Custom equality check on defaultMemoize feeding a rebuilt-but-equal input
// ---------------------------------------------------------------------------

test('custom shallow equality lets rebuilt-but-equal input skip recompute', () => {
  function shallowEqualityCheck(a, b) {
    if (Object.is(a, b)) return true;
    if (
      typeof a !== 'object' ||
      typeof b !== 'object' ||
      a === null ||
      b === null
    ) {
      return false;
    }
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    return ka.every((k) => Object.is(a[k], b[k]));
  }

  let combinerCalls = 0;
  const memoizedCombiner = defaultMemoize((obj) => {
    combinerCalls++;
    return `count=${obj.count}`;
  }, shallowEqualityCheck);

  // Simulate a selector layer that rebuilds an intermediate object each run.
  const selectSummary = (state) =>
    memoizedCombiner({ count: state.items.length, tag: state.tag });

  const s1 = { items: [1, 2], tag: 'a' };
  assert.equal(selectSummary(s1), 'count=2');
  assert.equal(combinerCalls, 1);

  // Rebuilt object with identical contents -> equal under shallow check.
  const s2 = { items: [1, 2], tag: 'b' }; // count same => new obj {count:2,...} equals old
  assert.equal(selectSummary(s2), 'count=2');
  assert.equal(combinerCalls, 1); // skipped!

  // Contents actually differ -> recompute.
  const s3 = { items: [1, 2, 3], tag: 'b' };
  assert.equal(selectSummary(s3), 'count=3');
  assert.equal(combinerCalls, 2);
});

test('createSelector built with custom memoizer via defaultMemoize skips recompute', () => {
  function shallowArrayEquality(a, b) {
    if (Object.is(a, b)) return true;
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) {
      return false;
    }
    return a.every((v, i) => Object.is(v, b[i]));
  }

  const memoizedJoin = defaultMemoize((arr) => arr.join(','), shallowArrayEquality);

  const selectJoined = createSelector(
    [(state) => state.flags.split('').map(Number)],
    memoizedJoin
  );

  const s1 = { flags: '101' };
  const s2 = { flags: '101' }; // same string -> same derived array contents
  assert.equal(selectJoined(s1), '1,0,1');
  assert.equal(selectJoined(s2), '1,0,1');
  assert.equal(selectJoined.recomputations(), 1);

  assert.equal(selectJoined({ flags: '110' }), '1,1,0');
  assert.equal(selectJoined.recomputations(), 2);
});

// ---------------------------------------------------------------------------
// createStructuredSelector
// ---------------------------------------------------------------------------

test('structured selector output identity stable when nothing changed', () => {
  const selectors = {
    count: (s) => s.items.length,
    theme: (s) => s.ui.theme,
  };
  const structured = createStructuredSelector(selectors);

  const s1 = { items: ['a'], ui: { theme: 'dark' } };
  const out1 = structured(s1);
  assert.deepEqual(out1, { count: 1, theme: 'dark' });

  // Irrelevant branch change -> same output object instance.
  const s2 = { ...s1, extra: true };
  const out2 = structured(s2);
  assert.strictEqual(out2, out1);

  // Relevant change -> new object.
  const s3 = { ...s2, items: ['a', 'b'] };
  const out3 = structured(s3);
  assert.notStrictEqual(out3, out1);
  assert.deepEqual(out3, { count: 2, theme: 'dark' });

  // Back to "equal by value" state but references differ -> still new object
  // because sub-selector outputs differ in identity from last run's values.
  const s4 = { ...s3, ui: { theme: 'light' } };
  const out4 = structured(s4);
  assert.deepEqual(out4, { count: 2, theme: 'light' });
  assert.notStrictEqual(out4, out3);
});

test('structured selector composes with createSelector and passes through rest args', () => {
  let calls = 0;
  const selectDoubled = createSelector([(s) => s.n], (n) => {
    calls++;
    return n * 2;
  });
  const structured = createStructuredSelector({ doubled: selectDoubled });

  const s1 = { n: 3 };
  const o1 = structured(s1);
  assert.deepEqual(o1, { doubled: 6 });
  assert.equal(calls, 1);

  const o2 = structured({ n: 3 });
  assert.strictEqual(o2, o1); // identity stable, combiner not rerun
  assert.equal(calls, 1);

  const o3 = structured({ n: 4 });
  assert.deepEqual(o3, { doubled: 8 });
  assert.equal(calls, 2);
});

// ---------------------------------------------------------------------------
// Chained selectors
// ---------------------------------------------------------------------------

test('chained selectors only recompute the affected stages', () => {
  const counts = { base: 0, mid: 0, leaf: 0 };

  const selectBase = createSelector(
    [(s) => s.todos.filter((t) => t.done).map((t) => t.id)],
    (ids) => {
      counts.base++;
      return ids;
    }
  );

  const selectMid = createSelector([selectBase], (ids) => {
    counts.mid++;
    return ids.length;
  });

  const selectLeaf = createSelector(
    [selectMid, (s) => s.label],
    (mid, label) => {
      counts.leaf++;
      return `${label}:${mid}`;
    }
  );

  const todos = [{ id: 7, done: true }];
  const s1 = { todos, label: 'done' };
  assert.equal(selectLeaf(s1), 'done:1');
  assert.deepEqual(counts, { base: 1, mid: 1, leaf: 1 });

  // Irrelevant change to `label`... wait, label IS relevant to leaf.
  // Change something irrelevant to all stages:
  const s2 = { ...s1, noise: 42 };
  assert.equal(selectLeaf(s2), 'done:1');
  assert.deepEqual(counts, { base: 1, mid: 1, leaf: 1 });

  // Change label: leaf recomputes, base/mid do not.
  const s3 = { ...s2, label: 'finished' };
  assert.equal(selectLeaf(s3), 'finished:1');
  assert.deepEqual(counts, { base: 1, mid: 1, leaf: 2 });

  // Change todos: base and mid recompute; leaf does NOT (mid result === 1).
  const s4 = { ...s3, todos: [{ id: 9, done: true }, { id: 10, done: false }] };
  assert.equal(selectBase(s4), undefined || selectLeaf(s4), 'drive evaluation');
  assert.equal(selectLeaf(s4), 'finished:1');
  assert.deepEqual(counts, { base: 2, mid: 2, leaf: 2 });
});

test('deep chain propagates invalidation exactly one stage per update', () => {
  const calls = { a: 0, b: 0, c: 0, d: 0 };

  const selA = createSelector([(s) => s.raw], (raw) => {
    calls.a++;
    return raw.toUpperCase();
  });
  const selB = createSelector([selA], (a) => {
    calls.b++;
    return a + '!';
  });
  const selC = createSelector([selB], (b) => {
    calls.c++;
    return b.repeat(2);
  });
  const selD = createSelector([selC, (s) => s.suffix], (c, suffix) => {
    calls.d++;
    return c + suffix;
  });

  const raw = 'hi';
  const s0 = { raw, suffix: '.' };
  assert.equal(selD(s0), 'HI!!HI!!.');
  assert.deepEqual(calls, { a: 1, b: 1, c: 1, d: 1 });

  // Only suffix changes -> just stage D.
  assert.equal(selD({ raw, suffix: '?' }), 'HI!!HI!!?');
  assert.deepEqual(calls, { a: 1, b: 1, c: 1, d: 2 });

  // Only raw changes -> A, B, C, D.
  assert.equal(selD({ raw: 'yo', suffix: '?' }), 'YO!!YO!!?');
  assert.deepEqual(calls, { a: 2, b: 2, c: 2, d: 3 });

  // Nothing relevant -> nothing recomputes.
  assert.equal(selD({ raw: 'yo', suffix: '?', junk: 1 }), 'YO!!YO!!?');
  assert.deepEqual(calls, { a: 2, b: 2, c: 2, d: 3 });
});

test('selector metadata exposes dependencies and resultFunc', () => {
  const input = (s) => s.x;
  const combiner = (x) => x + 1;
  const sel = createSelector([input], combiner);
  assert.equal(sel.resultFunc, combiner);
  assert.deepEqual(sel.dependencies, [input]);
});
"})
